(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-633":{scenario:{company:"Ngân Hà BIM Studio",supervisor:{name:"Vũ Hoàng Nam",role:{vi:"Quản lý BIM dự án",en:"Project BIM Manager"}},ref_code:"BIM-0731",title:{vi:"Một tọa độ. Một mô hình liên kết. Không va chạm ẩn.",en:"One coordinate system. One federated model. No hidden clashes."},brief:{vi:"Bạn phối hợp mô hình liên kết BIM-0731 của tòa văn phòng 12 tầng. Mô hình MEP đang liên kết sai chế độ nên lệch so với kết cấu, sinh hàng nghìn xung đột giả. Ở hành lang tầng 3: trần hoàn thiện +2 700 mm, hệ khung trần dày 80 mm, khe hở lắp đặt dưới ống tối thiểu 50 mm; ống gió cao 350 mm, bảo ôn 25 mm, đáy dầm +3 250 mm. Hãy sửa chế độ liên kết và cao độ đáy ống gió tối thiểu (BOD), rồi lập báo cáo có căn cứ.",en:"You coordinate federated model BIM-0731 of a 12-storey office. The MEP model is linked in the wrong mode, so it sits offset from the structure and creates thousands of false clashes. Level 3 corridor: finished ceiling +2,700 mm, ceiling grid 80 mm deep, minimum gap under the duct 50 mm; duct 350 mm high with 25 mm insulation; beam soffit +3,250 mm. Correct the link mode and the minimum bottom of duct (BOD), then write an evidence-based report."},reference_title:{vi:"Kế hoạch thực hiện BIM & phiếu phối hợp trần đã duyệt",en:"Approved BIM execution plan & ceiling coordination sheet"},fields:[{id:"LINK_MODE",label:{vi:"Chế độ liên kết mô hình MEP",en:"MEP model link mode"},initial:"ORIGIN-TO-ORIGIN",expected:"SHARED-COORD",choices:["ORIGIN-TO-ORIGIN","SHARED-COORD","CENTER-TO-CENTER"],reference:"Kế hoạch thực hiện BIM (BEP) mục 4.3",ref_value:{vi:"Mọi mô hình bộ môn định vị theo hệ tọa độ chia sẻ lấy từ mô hình mốc khảo sát",en:"All discipline models are positioned by the shared coordinate system from the survey model"},hint:{vi:"Mô hình MEP được dựng với gốc nội bộ khác kết cấu; chỉ hệ tọa độ chia sẻ mới khớp vị trí thật.",en:"The MEP model was built on a different internal origin; only shared coordinates align true positions."}},{id:"BOD_MM",label:{vi:"Cao độ đáy ống gió tối thiểu BOD (mm)",en:"Minimum bottom of duct BOD (mm)"},initial:"2700",expected:"2830",reference:"Phiếu phối hợp trần hành lang tầng 3",ref_value:{vi:"Trần hoàn thiện +2 700; khung trần 80 mm; khe hở lắp đặt 50 mm; đáy dầm +3 250",en:"Finished ceiling +2,700; ceiling grid 80 mm; installation gap 50 mm; beam soffit +3,250"},hint:{vi:"Bản nháp đặt đáy ống đúng bằng mặt trần, chưa tính phần khung trần và khe hở lắp đặt.",en:"The draft sets the duct bottom at the ceiling face, ignoring the grid depth and installation gap."}}],sop32:{vi:"BOD tối thiểu = cao độ trần hoàn thiện + chiều dày hệ khung trần + khe hở lắp đặt. Sau đó kiểm tra: BOD + chiều cao ống + 2 x chiều dày bảo ôn phải không vượt cao độ đáy dầm.",en:"Minimum BOD = finished ceiling level + ceiling grid depth + installation gap. Then check: BOD + duct height + 2 x insulation thickness must not exceed the beam soffit level."},context:{label:"CDE / BIM-0731",metrics:[{label:{vi:"Xung đột cứng",en:"Hard clashes"},value:"1,284"},{label:{vi:"Lệch MEP so với kết cấu",en:"MEP offset from structure"},value:"18.400 m E / 6.250 m N"},{label:{vi:"Đáy dầm hành lang",en:"Corridor beam soffit"},value:"+3,250 mm"}]},terminal:{system:"bim-coord",settable:["LINK_MODE","BOD_MM"],commands:[{cmd:"status",out:{vi:"Mô hình liên kết: ARC_R24, STR_R24, MEP_R24; chế độ liên kết MEP: ORIGIN-TO-ORIGIN; 1 284 xung đột cứng mới ở lần chạy gần nhất",en:"Linked models: ARC_R24, STR_R24, MEP_R24; MEP link mode: ORIGIN-TO-ORIGIN; 1,284 new hard clashes in the latest run"}},{cmd:"coord check",out:{vi:"MEP so với STR: lệch 18,400 m hướng Đông, 6,250 m hướng Bắc, góc xoay 0°; ARC và STR khớp tọa độ chia sẻ",en:"MEP vs STR: offset 18.400 m East, 6.250 m North, rotation 0°; ARC and STR match on shared coordinates"}},{cmd:"cat bep.txt",out:{vi:"BEP 4.3: mọi mô hình định vị theo hệ tọa độ chia sẻ từ mô hình mốc khảo sát; dung sai va chạm cứng 10 mm",en:"BEP 4.3: all models positioned by shared coordinates from the survey model; hard clash tolerance 10 mm"}},{cmd:"clash top",out:{vi:"Nhóm lớn nhất khi đã bỏ lệch tọa độ: 46 va chạm giữa ống gió hành lang tầng 3 và trần, BOD đang đặt +2700",en:"Largest group once the offset is removed: 46 clashes between level 3 corridor ducts and the ceiling, BOD set at +2700"}},{cmd:"cat ceiling-spec.txt",out:{vi:"Trần hoàn thiện +2700; khung trần 80 mm; khe hở lắp đặt dưới ống tối thiểu 50 mm; đáy dầm +3250",en:"Finished ceiling +2700; ceiling grid 80 mm; minimum installation gap under duct 50 mm; beam soffit +3250"}}]},crisis:{vi:"Trước buổi họp với chủ đầu tư, giám đốc dự án nhắn: “Đánh dấu hết xung đột là Approved để báo cáo 0 va chạm, xuất bản vẽ phối hợp luôn. Ra công trường thợ tự xử lý được.”",en:"Before the client meeting the project director texts: “Mark every clash as Approved so we report zero clashes and issue the coordination drawings now. The site crews will sort it out.”"},options:{safe:{vi:"Không đánh dấu giả; liên kết lại theo tọa độ chia sẻ, chạy lại kiểm tra va chạm, báo quản lý BIM số xung đột thật và đề xuất họp phối hợp xử lý theo ưu tiên trước khi phát hành.",en:"Do not falsify statuses; relink by shared coordinates, rerun clash detection, report the real clash count to the BIM manager and propose a priority coordination meeting before issue."},shortcut:{vi:"Đánh dấu Approved toàn bộ xung đột để báo cáo đẹp, để công trường xử lý sau.",en:"Mark all clashes Approved for a clean report and let the site fix them later."},wait:{vi:"Hoãn báo cáo, không phát hành gì và chờ giám đốc dự án tự quyết.",en:"Postpone the report, issue nothing and wait for the project director to decide."}},questions:{vi:["Giải thích nguyên nhân hàng nghìn xung đột giả, vì sao liên kết theo tọa độ chia sẻ khắc phục được, và cách bạn xác định BOD.","Việc đánh dấu Approved hàng loạt gây rủi ro gì cho thi công và cho trách nhiệm pháp lý của nhóm BIM?"],en:["Explain the cause of thousands of false clashes, why shared coordinates fix it, and how you determined the BOD.","What risks does bulk-approving clashes create for construction and for the BIM team's liability?"]},hints:{vi:["Chạy lệnh kiểm tra tọa độ và đối chiếu với BEP trước khi xem xét từng xung đột riêng lẻ.","Theo SOP mục 3.2, cộng đủ các lớp nằm giữa mặt trần và đáy ống, rồi kiểm tra lại với đáy dầm.","SOP mục 4.2: trạng thái xung đột phải phản ánh đúng thực tế; áp lực làm đẹp báo cáo phải được báo lên trên."],en:["Run the coordinate check and compare it with the BEP before reviewing individual clashes.","Under SOP 3.2, add every layer between the ceiling face and the duct bottom, then check against the beam soffit.","SOP 4.2: clash statuses must reflect reality; escalate any pressure to dress up the report."]}},learning:{summary:{vi:"Kỹ sư mô hình thông tin công trình (BIM Coordinator) quản lý, liên kết và kiểm tra mô hình của các bộ môn kiến trúc, kết cấu, cơ điện trên môi trường dữ liệu chung (CDE). Họ phát hiện xung đột trước khi thi công, điều phối họp xử lý, kiểm soát quy ước đặt tên, mức độ phát triển và chất lượng dữ liệu. Nghề đòi hỏi hiểu kỹ thuật đa bộ môn, thành thạo phần mềm và quy trình quản lý thông tin theo ISO 19650.",en:"A BIM coordinator manages, federates and checks architectural, structural and MEP models in a common data environment (CDE). They detect clashes before construction, run resolution meetings and control naming conventions, level of development and data quality. The role requires multi-discipline technical understanding, software fluency and information management processes aligned with ISO 19650."},responsibilities:{vi:["Thiết lập hệ tọa độ chia sẻ, mẫu dự án và quy ước đặt tên theo kế hoạch thực hiện BIM (BEP).","Liên kết mô hình các bộ môn, chạy kiểm tra xung đột và phân loại theo mức ưu tiên.","Chủ trì họp phối hợp, giao việc xử lý qua BCF và theo dõi đến khi đóng.","Kiểm tra chất lượng mô hình: mức độ phát triển, thông tin thuộc tính, trạng thái phát hành trên CDE.","Trích xuất bản vẽ phối hợp, khối lượng và báo cáo tiến độ mô hình cho quản lý dự án."],en:["Set up shared coordinates, project templates and naming conventions per the BIM execution plan (BEP).","Federate discipline models, run clash detection and rank issues by priority.","Chair coordination meetings, assign fixes through BCF and track them to closure.","Check model quality: level of development, property data and publishing status in the CDE.","Extract coordination drawings, quantities and model progress reports for project management."]},competencies:[{name:{vi:"Phối hợp đa bộ môn",en:"Multi-discipline coordination"},desc:{vi:"Hiểu ràng buộc kiến trúc, kết cấu, cơ điện để đề xuất phương án tránh va chạm hợp lý.",en:"Understand architectural, structural and MEP constraints to propose sensible clash-free routes."}},{name:{vi:"Quản lý thông tin theo ISO 19650",en:"ISO 19650 information management"},desc:{vi:"Áp dụng CDE, mã trạng thái phù hợp, quy ước đặt tên và quy trình phê duyệt thông tin.",en:"Apply the CDE, suitability codes, naming conventions and information approval workflows."}},{name:{vi:"Kiểm tra xung đột",en:"Clash detection"},desc:{vi:"Thiết lập bộ kiểm tra, dung sai, lọc xung đột giả và nhóm xung đột theo nguyên nhân.",en:"Configure tests and tolerances, filter false clashes and group issues by root cause."}},{name:{vi:"Tự động hóa & dữ liệu",en:"Automation & data"},desc:{vi:"Dùng lập trình trực quan, bộ lọc và bảng thống kê để kiểm tra dữ liệu hàng loạt.",en:"Use visual scripting, filters and schedules to validate data at scale."}},{name:{vi:"Minh bạch & trách nhiệm",en:"Transparency & accountability"},desc:{vi:"Báo cáo đúng số liệu xung đột và tình trạng mô hình, không che giấu rủi ro.",en:"Report true clash counts and model status without hiding risks."}}],knowledge:{vi:["ISO 19650-1 và ISO 19650-2:2018 - Quản lý thông tin bằng BIM, giai đoạn chuyển giao tài sản.","Quyết định 258/QĐ-TTg năm 2023 phê duyệt lộ trình áp dụng BIM trong hoạt động xây dựng.","Định dạng trao đổi mở IFC (ISO 16739) và định dạng trao đổi vấn đề BCF của buildingSMART.","Đặc tả mức độ phát triển LOD 100-500 để quy định nội dung mô hình theo giai đoạn.","Nguyên tắc định vị: gốc nội bộ, điểm cơ sở dự án, điểm khảo sát và hệ tọa độ chia sẻ."],en:["ISO 19650-1 and ISO 19650-2:2018 - Information management using BIM, delivery phase of assets.","Decision 258/QD-TTg of 2023 approving the roadmap for BIM adoption in construction in Vietnam.","The open IFC exchange format (ISO 16739) and the buildingSMART BCF issue format.","LOD 100-500 specification defining model content by project stage.","Positioning principles: internal origin, project base point, survey point and shared coordinates."]},tools:["Phần mềm mô hình BIM kiến trúc, kết cấu, MEP","Phần mềm kiểm tra xung đột và mô phỏng 4D","Môi trường dữ liệu chung (CDE)","Trình xem IFC","Công cụ lập trình trực quan"],kpis:{vi:["Số xung đột cứng còn mở trước mỗi đợt phát hành bản vẽ.","Thời gian trung bình để đóng một vấn đề BCF.","Tỷ lệ mô hình đạt kiểm tra chất lượng ngay lần đầu.","Số yêu cầu thay đổi tại công trường do lỗi phối hợp."],en:["Open hard clashes before each drawing issue.","Average time to close a BCF issue.","Share of models passing quality checks first time.","Site change requests caused by coordination errors."]},day:[{time:"08:30",vi:"Tải mô hình mới nhất của các bộ môn từ CDE, kiểm tra tọa độ và trạng thái phát hành.",en:"Download the latest discipline models from the CDE and check coordinates and status."},{time:"10:00",vi:"Chạy kiểm tra xung đột, lọc xung đột giả và nhóm theo khu vực, hệ thống.",en:"Run clash tests, filter false clashes and group them by zone and system."},{time:"13:30",vi:"Chủ trì họp phối hợp, thống nhất phương án và giao việc qua BCF.",en:"Chair the coordination meeting, agree solutions and assign actions through BCF."},{time:"15:30",vi:"Kiểm tra thông tin thuộc tính và mức độ phát triển của mô hình theo BEP.",en:"Check property data and level of development against the BEP."},{time:"17:00",vi:"Cập nhật báo cáo xung đột, xuất bản vẽ phối hợp và lưu vết trên CDE.",en:"Update the clash report, issue coordination drawings and log the trail in the CDE."}],mistakes:{vi:["Liên kết mô hình theo gốc nội bộ thay vì tọa độ chia sẻ, tạo hàng loạt xung đột giả.","Đặt dung sai kiểm tra bằng 0 hoặc quá lớn, làm nhiễu hoặc bỏ sót xung đột thật.","Đánh dấu xung đột đã duyệt để làm đẹp báo cáo khi chưa có phương án xử lý."],en:["Linking models origin to origin instead of by shared coordinates, creating mass false clashes.","Setting the clash tolerance to zero or too large, causing noise or missed real clashes.","Marking clashes approved to dress up the report before any solution exists."]},career:[{vi:"Dựng hình BIM (BIM Modeler)",en:"BIM modeler"},{vi:"Điều phối BIM (BIM Coordinator)",en:"BIM coordinator"},{vi:"Quản lý BIM dự án",en:"Project BIM manager"},{vi:"Giám đốc chuyển đổi số xây dựng",en:"Digital construction director"}],glossary:[{term:"CDE",vi:"Môi trường dữ liệu chung để lưu, chia sẻ và phê duyệt thông tin dự án theo trạng thái.",en:"Common data environment to store, share and approve project information by status."},{term:"BEP",vi:"Kế hoạch thực hiện BIM quy định vai trò, tiêu chuẩn, tọa độ, phần mềm và quy trình trao đổi.",en:"BIM execution plan defining roles, standards, coordinates, software and exchange processes."},{term:"Clash detection",vi:"Kiểm tra tự động va chạm cứng, va chạm mềm giữa các đối tượng trong mô hình liên kết.",en:"Automated check for hard and soft clashes between objects in a federated model."},{term:"LOD",vi:"Mức độ phát triển của đối tượng mô hình, thể hiện độ chi tiết hình học và độ tin cậy thông tin.",en:"Level of development of model elements, expressing geometric detail and information reliability."},{term:"Shared coordinates",vi:"Hệ tọa độ chung gắn với mốc khảo sát, giúp mọi mô hình định vị đúng vị trí thực.",en:"Common coordinate system tied to survey control so every model sits at its true location."}],quiz:[{q:{vi:"Trần hoàn thiện +2 600 mm, khung trần 100 mm, khe hở lắp đặt 50 mm. BOD tối thiểu là bao nhiêu?",en:"Finished ceiling +2,600 mm, ceiling grid 100 mm, installation gap 50 mm. What is the minimum BOD?"},options:{vi:["+2 600 mm","+2 700 mm","+2 750 mm","+2 650 mm"],en:["+2,600 mm","+2,700 mm","+2,750 mm","+2,650 mm"]},answer:2,explain:{vi:"Cộng cao độ trần, chiều dày khung trần và khe hở lắp đặt: BOD = 2 600 + 100 + 50 = +2 750 mm.",en:"BOD = 2,600 + 100 + 50 = +2,750 mm."}},{q:{vi:"Bộ tiêu chuẩn quốc tế nào hướng dẫn quản lý thông tin dự án bằng BIM?",en:"Which international series guides project information management using BIM?"},options:{vi:["ISO 9001","ISO 19650","ISO 14001","ISO 45001"],en:["ISO 9001","ISO 19650","ISO 14001","ISO 45001"]},answer:1,explain:{vi:"ISO 19650 quy định khái niệm, CDE và quy trình quản lý thông tin bằng BIM.",en:"ISO 19650 sets the concepts, the CDE and the processes for information management using BIM."}},{q:{vi:"Giám đốc dự án yêu cầu đánh dấu toàn bộ xung đột là Approved trước buổi họp. Bạn làm gì?",en:"The project director asks you to mark every clash as Approved before the meeting. What do you do?"},options:{vi:["Làm theo vì là yêu cầu cấp trên","Đánh dấu một nửa số xung đột","Xóa bớt xung đột khỏi báo cáo","Từ chối làm giả, báo cáo số liệu thật và đề xuất kế hoạch xử lý"],en:["Comply because a superior asked","Mark half of the clashes","Remove some clashes from the report","Refuse to falsify, report real figures and propose a resolution plan"]},answer:3,explain:{vi:"Trạng thái giả che giấu rủi ro thi công và làm sai lệch hồ sơ; cần minh bạch kèm kế hoạch xử lý.",en:"False statuses hide construction risk and corrupt the record; transparency with a resolution plan is required."}},{q:{vi:"Mô hình MEP lệch 18 m so với kết cấu dù hình học đúng. Nguyên nhân thường gặp nhất là gì?",en:"The MEP model is 18 m away from the structure though its geometry is correct. What is the most common cause?"},options:{vi:["Liên kết theo gốc nội bộ thay vì tọa độ chia sẻ","Thiếu lớp bảo ôn ống gió","Thiếu thông tin thuộc tính","Sai mức độ phát triển LOD"],en:["Linked by internal origin instead of shared coordinates","Missing duct insulation","Missing property data","Wrong LOD"]},answer:0,explain:{vi:"Lệch tịnh tiến đều giữa các mô hình là dấu hiệu điển hình của việc không dùng hệ tọa độ chia sẻ.",en:"A uniform translation between models is the classic sign that shared coordinates were not used."}}],tools_en:["Architectural, structural and MEP BIM software","Clash detection and 4D simulation software","Common data environment (CDE)","IFC viewer","Visual programming tool"]}}})})(window.KKR);
